/*
 * A067546  Determinant of an n X n matrix whose diagonal are the first n
 *          nonprime numbers and all other elements are 1's.
 * https://oeis.org/A067546
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = ∏_{k=2}^{n} (nonprime_k – 1) where nonprime_k is the k‑th
 *            non‑prime number (1,4,6,8,9,10,12,…). The non‑prime list is
 *            generated by a sieve; the product is then computed
 *            multiplicatively
 * Range:     u8 n <= 4, u16 n <= 6, u32 n <= 11, u64 n <= 18, u128 n <= 30,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/* Sieve upper bound – more than enough to provide the first 10 000
   non‑prime numbers (≈ 12 000 non‑primes). */
#define SIEVE_LIMIT 2000000

/* Prime flag table and non‑prime list. */
static bool is_prime[SIEVE_LIMIT + 1];
static uint64_t nonprimes_arr[SIEVE_LIMIT + 1];
static size_t nonprimes_count = 0;
static bool initialized = false;

/* One‑time sieve and non‑prime extraction. */
static void build_sieve(void)
{
    for (idx_t i = 0; i <= SIEVE_LIMIT; ++i)
        is_prime[i] = true;
    is_prime[0] = is_prime[1] = false;

    for (idx_t p = 2; (uint64_t)p * p <= SIEVE_LIMIT; ++p)
        if (is_prime[p])
            for (idx_t k = p * p; k <= SIEVE_LIMIT; k += p)
                is_prime[k] = false;

    nonprimes_count = 0;
    for (idx_t i = 1; i <= SIEVE_LIMIT; ++i)
        if (!is_prime[i])
            nonprimes_arr[nonprimes_count++] = (uint64_t)i;

    initialized = true;
}

/* ------------------------------------------------------------------ */
/*  Required sequence function                                       */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (!initialized)
        build_sieve();

    if (n == 0)                 /* undefined, but return 0 for safety */
        return (seq_t)0;
    if (n == 1)                 /* first term of the sequence */
        return (seq_t)1;

    seq_t result = (seq_t)1;
    /* Multiply (nonprime_k – 1) for k = 2 … n. */
    for (idx_t k = 2; k <= n; ++k) {
        uint64_t val = nonprimes_arr[k - 1] - 1;   /* k‑th non‑prime */
        result = result * (seq_t)val;
    }
    return result;
}
